contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(uint256 burnAmount) public {
        address owner = c.owner();

        uint256 supplyBefore = c.totalSupply();
        uint256 ownerBalBefore = c.balanceOf(owner);

        require(burnAmount <= ownerBalBefore);

        bool reverted;
        try c.burn(burnAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 supplyAfter = c.totalSupply();
        uint256 ownerBalAfter = c.balanceOf(owner);

        if (!reverted) {
            assert(supplyAfter == supplyBefore - burnAmount && ownerBalAfter == ownerBalBefore - burnAmount);
        } else {
            assert(supplyAfter == supplyBefore && ownerBalAfter == ownerBalBefore);
        }
    }
}

